//! The graphics backends, checked against the C library's `grf_log.c`.
//!
//! `grf_log_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/grf_log_probe.c`, which drives `grf_log.c` through
//! a fixed sequence of calls covering every function and attribute of the
//! C graphics interface, and records what each call returned, the call log
//! and the SVG. Each backend replays the same sequence here.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "grf_log_oracle/cases.rs"]
mod cases;

use cases::{Call, Expected};
use starlink_ast::error::ErrorCode;
use starlink_ast::grf::{
    Grf, GrfAttr, GrfCap, GrfPrimitive, Justification, LogGrf, SvgGrf, SvgOptions,
};

fn attr(name: &str) -> GrfAttr {
    match name {
        "Style" => GrfAttr::Style,
        "Width" => GrfAttr::Width,
        "Size" => GrfAttr::Size,
        "Font" => GrfAttr::Font,
        "Colour" => GrfAttr::Colour,
        _ => panic!("unknown attribute {name}"),
    }
}

fn prim(name: &str) -> GrfPrimitive {
    match name {
        "Text" => GrfPrimitive::Text,
        "Line" => GrfPrimitive::Line,
        "Mark" => GrfPrimitive::Mark,
        _ => panic!("unknown primitive {name}"),
    }
}

fn cap(name: &str) -> GrfCap {
    match name {
        "Escapes" => GrfCap::Escapes,
        "MJust" => GrfCap::MJust,
        "Scales" => GrfCap::Scales,
        _ => panic!("unknown capability {name}"),
    }
}

fn bits(v: &[f32]) -> Vec<u32> {
    v.iter().map(|x| x.to_bits()).collect()
}

/// Calls whose result differs from C's by design, each with its reason:
/// text that is not ASCII, which C, written before Unicode, measures by
/// bytes and the port by characters. They are left out of the comparison,
/// with the log lines they write, and `text_width_exclusions_still_differ`
/// fails when one matches C again.
const TEXT_WIDTH_EXCLUDED: &[(usize, &str)] = &[
    (
        26,
        "the extent of \"°\": C counts its two UTF-8 bytes as two characters",
    ),
    (
        28,
        "the extent of \"-30°\": C counts the degree sign's two bytes as two characters",
    ),
];

/// Calls whose SVG differs from C's by design: text holding characters XML
/// gives a meaning, which C's `grf_log.c` writes as given, making its SVG
/// invalid, and the port escapes. Their `<text>` lines are left out of the
/// SVG comparison, and `xml_escape_exclusions_still_differ` fails when one
/// matches C again.
const XML_ESCAPE_EXCLUDED: &[(usize, &str)] = &[(
    84,
    "the text a<b & \"c\", which C writes into its SVG unescaped",
)];

/// The text drawn by an excluded `Text` call.
fn escaped_call_text(i: usize) -> &'static str {
    match cases::CALLS[i].0 {
        Call::Text(t, ..) => t,
        ref other => panic!("call {i} is not a text: {other:?}"),
    }
}

/// An SVG with the `<text>` lines of the XML-escape exclusions removed, as
/// C writes them and as the port does.
fn without_escaped(svg: &str) -> String {
    svg.lines()
        .filter(|l| {
            !XML_ESCAPE_EXCLUDED.iter().any(|&(i, _)| {
                let t = escaped_call_text(i);
                let escaped = t
                    .replace('&', "&amp;")
                    .replace('<', "&lt;")
                    .replace('>', "&gt;")
                    .replace('"', "&quot;");
                l.ends_with(&format!(">{t}</text>")) || l.ends_with(&format!(">{escaped}</text>"))
            })
        })
        .map(|l| format!("{l}\n"))
        .collect()
}

/// The text of an excluded call.
fn excluded_text(i: usize) -> &'static str {
    match cases::CALLS[i].0 {
        Call::TxExt(t, ..) => t,
        ref other => panic!("call {i} is not a text extent: {other:?}"),
    }
}

/// A log or SVG with the lines of the excluded calls removed.
fn without_excluded(text: &str) -> String {
    text.lines()
        .filter(|l| {
            !TEXT_WIDTH_EXCLUDED
                .iter()
                .any(|&(i, _)| l.starts_with(&format!("GTxExt \"{}\"", excluded_text(i))))
        })
        .map(|l| format!("{l}\n"))
        .collect()
}

/// Replay the probe's calls through `grf`, checking each return.
fn replay(grf: &mut dyn Grf) {
    for (i, (call, want)) in cases::CALLS.iter().enumerate() {
        if TEXT_WIDTH_EXCLUDED.iter().any(|&(x, _)| x == i) {
            if let Call::TxExt(t, x, y, j, up) = call {
                let _ = grf.text_extent(t, *x, *y, Justification::from_code(j).unwrap(), *up);
            }
            continue;
        }
        let what = format!("call {i}: {call:?}");
        match (call, want) {
            (Call::Scales, Expected::Pair(p)) => {
                assert_eq!(bits(&grf.scales().unwrap()), bits(p), "{what}");
            }
            (Call::Qch, Expected::Pair(p)) => {
                assert_eq!(bits(&grf.char_height().unwrap()), bits(p), "{what}");
            }
            (Call::TxExt(t, x, y, j, up), want) => {
                let got = grf.text_extent(t, *x, *y, Justification::from_code(j).unwrap(), *up);
                match want {
                    Expected::Box(bx, by) => {
                        let got = got.unwrap();
                        assert_eq!((bits(&got.x), bits(&got.y)), (bits(bx), bits(by)), "{what}");
                    }
                    Expected::Error => {
                        assert_eq!(got.unwrap_err().code(), ErrorCode::Grfer, "{what}");
                    }
                    _ => panic!("{what}: unexpected expectation {want:?}"),
                }
            }
            (Call::Text(t, x, y, j, up), Expected::Done) => {
                grf.text(t, *x, *y, Justification::from_code(j).unwrap(), *up)
                    .unwrap();
            }
            (Call::Line(x, y), Expected::Done) => grf.line(x, y).unwrap(),
            (Call::Mark(x, y, m), Expected::Done) => grf.mark(x, y, *m).unwrap(),
            (Call::Attr(a, v, p), Expected::Previous(old)) => {
                assert_eq!(grf.attr(attr(a), *v, prim(p)).unwrap(), *old, "{what}");
            }
            (Call::Cap(c, v), Expected::Cap(has)) => {
                assert_eq!(grf.cap(cap(c), *v), *has, "{what}");
            }
            (Call::BBuf, Expected::Done) => grf.begin_buffer().unwrap(),
            (Call::EBuf, Expected::Done) => grf.end_buffer().unwrap(),
            (Call::Flush, Expected::Done) => grf.flush().unwrap(),
            _ => panic!("{what}: unexpected expectation {want:?}"),
        }
    }
}

/// Assert two multi-line texts are equal, reporting the first differing
/// line.
fn assert_lines_eq(got: &str, want: &str, what: &str) {
    if got == want {
        return;
    }
    for (i, (g, w)) in got.lines().zip(want.lines()).enumerate() {
        assert_eq!(g, w, "{what}: first difference at line {}", i + 1);
    }
    assert_eq!(
        got.len(),
        want.len(),
        "{what}: one is a prefix of the other"
    );
    panic!("{what}: texts differ only in line endings");
}

#[test]
fn log_grf_matches_the_c_library() {
    let mut grf = LogGrf::new(Vec::new());
    replay(&mut grf);
    let log = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert_lines_eq(
        &without_excluded(&log),
        &without_excluded(cases::LOG),
        "log",
    );
}

#[test]
fn svg_grf_matches_the_c_library() {
    let mut grf = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    replay(&mut grf);
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert_lines_eq(
        &without_escaped(&without_excluded(&svg)),
        &without_escaped(&without_excluded(cases::SVG)),
        "svg",
    );
}

#[test]
fn xml_escape_exclusions_still_differ() {
    for &(i, reason) in XML_ESCAPE_EXCLUDED {
        let (Call::Text(t, x, y, j, up), _) = &cases::CALLS[i] else {
            panic!("call {i} is not a text");
        };
        let mut grf = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
        grf.text(t, *x, *y, Justification::from_code(j).unwrap(), *up)
            .unwrap();
        let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
        assert!(
            !svg.contains(&format!(">{t}</text>")),
            "call {i} now writes the text as C does ({reason})"
        );
    }
}

#[test]
fn text_width_exclusions_still_differ() {
    for &(i, reason) in TEXT_WIDTH_EXCLUDED {
        let (Call::TxExt(t, x, y, j, up), Expected::Box(bx, _)) = &cases::CALLS[i] else {
            panic!("call {i} is not a text extent with a box");
        };
        let mut grf = LogGrf::new(Vec::new());
        let got = grf
            .text_extent(t, *x, *y, Justification::from_code(j).unwrap(), *up)
            .unwrap();
        assert_ne!(bits(&got.x), bits(bx), "call {i} now matches C ({reason})");
    }
}

/// The page size can be set field by field, which is how options added
/// later stay compatible.
#[test]
fn svg_options_set_the_page_size() {
    let mut options = SvgOptions::default();
    assert_eq!((options.width, options.height), (720, 540));
    options.width = 800;
    options.height = 600;
    let grf = SvgGrf::new(Vec::new(), options).unwrap();
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert!(
        svg.contains("width=\"800\" height=\"600\" viewBox=\"0 0 800 600\""),
        "{svg}"
    );
    assert!(svg.ends_with("</svg>\n"), "{svg}");
}

#[test]
fn justification_round_trips_its_code() {
    for v in ["M", "B", "C", "T"] {
        for h in ["L", "C", "R"] {
            let code = format!("{v}{h}");
            let just = Justification::from_code(&code).unwrap();
            assert_eq!(just.code(), code.as_bytes(), "{code}");
        }
    }
    for bad in ["XX", "C", "CCC", "LC", ""] {
        assert_eq!(
            Justification::from_code(bad).unwrap_err().code(),
            ErrorCode::Grfer,
            "{bad:?}"
        );
    }
}

#[test]
fn mismatched_points_are_an_error() {
    let mut log = LogGrf::new(Vec::new());
    let mut svg = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    for grf in [&mut log as &mut dyn Grf, &mut svg as &mut dyn Grf] {
        assert_eq!(
            grf.line(&[0.1, 0.2], &[0.1]).unwrap_err().code(),
            ErrorCode::Grfer
        );
        assert_eq!(
            grf.mark(&[0.1], &[], 1).unwrap_err().code(),
            ErrorCode::Grfer
        );
    }
}

/// The provided backends take `BAD_VALUE` as a query, as the C library
/// does: nothing is set and nothing is logged.
#[test]
fn provided_backends_take_a_bad_value_as_a_query() {
    use starlink_ast::constants::BAD_VALUE;
    let mut log = LogGrf::new(Vec::new());
    let mut svg = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    for grf in [&mut log as &mut dyn Grf, &mut svg as &mut dyn Grf] {
        grf.attr(GrfAttr::Colour, Some(3.0), GrfPrimitive::Line)
            .unwrap();
        assert_eq!(
            grf.attr(GrfAttr::Colour, Some(BAD_VALUE), GrfPrimitive::Line)
                .unwrap(),
            3.0
        );
        assert_eq!(
            grf.attr(GrfAttr::Colour, None, GrfPrimitive::Line).unwrap(),
            3.0
        );
    }
    let log = String::from_utf8(log.finish().unwrap()).unwrap();
    assert_eq!(log, "GAttr COLOUR=3.0000 prim=LINE\n");
}

/// A backend need not write the buffering and flushing methods, whose
/// defaults do nothing.
#[test]
fn buffering_and_flushing_default_to_nothing() {
    use starlink_ast::error::AstResult;
    use starlink_ast::grf::TextBox;

    struct Minimal;
    impl Grf for Minimal {
        fn line(&mut self, _x: &[f32], _y: &[f32]) -> AstResult<()> {
            Ok(())
        }
        fn mark(&mut self, _x: &[f32], _y: &[f32], _marker: i32) -> AstResult<()> {
            Ok(())
        }
        fn text(
            &mut self,
            _t: &str,
            _x: f32,
            _y: f32,
            _j: Justification,
            _up: [f32; 2],
        ) -> AstResult<()> {
            Ok(())
        }
        fn text_extent(
            &mut self,
            _t: &str,
            _x: f32,
            _y: f32,
            _j: Justification,
            _up: [f32; 2],
        ) -> AstResult<TextBox> {
            Ok(TextBox {
                x: [0.0; 4],
                y: [0.0; 4],
            })
        }
        fn char_height(&mut self) -> AstResult<[f32; 2]> {
            Ok([0.01, 0.01])
        }
        fn scales(&mut self) -> AstResult<[f32; 2]> {
            Ok([1.0, 1.0])
        }
        fn attr(&mut self, _a: GrfAttr, _v: Option<f64>, _p: GrfPrimitive) -> AstResult<f64> {
            Ok(1.0)
        }
        fn cap(&mut self, _c: GrfCap, _v: i32) -> bool {
            false
        }
    }
    let mut grf = Minimal;
    grf.begin_buffer().unwrap();
    grf.end_buffer().unwrap();
    grf.flush().unwrap();
}

/// Text goes into the SVG escaped, so markup characters in a label keep the
/// SVG well formed.
#[test]
fn text_is_escaped_for_xml() {
    let mut grf = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    let cc = Justification::from_code("CC").unwrap();
    grf.text("a<b & \"c\" > d", 0.5, 0.5, cc, [0.0, 1.0])
        .unwrap();
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert!(
        svg.contains(">a&lt;b &amp; &quot;c&quot; &gt; d</text>"),
        "{svg}"
    );
}

/// Characters XML does not allow in a document (the C0 controls but tab,
/// newline and carriage return, and U+FFFE and U+FFFF), which a label could
/// hold, are drawn as U+FFFD, so the SVG stays well formed.
#[test]
fn characters_xml_forbids_are_replaced() {
    let mut grf = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    let cc = Justification::from_code("CC").unwrap();
    grf.text("a\u{1}b\u{0}c\td\u{FFFF}e", 0.5, 0.5, cc, [0.0, 1.0])
        .unwrap();
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert!(
        svg.contains(">a\u{FFFD}b\u{FFFD}c\td\u{FFFD}e</text>"),
        "{svg}"
    );
}

/// With erase_under_text, each text's box is filled with the background
/// before the text is drawn.
#[test]
fn erase_under_text_fills_the_text_box() {
    let mut options = SvgOptions::default();
    options.erase_under_text = true;
    let mut grf = SvgGrf::new(Vec::new(), options).unwrap();
    let bl = Justification::from_code("BL").unwrap();
    let tbox = grf
        .text_extent("Label", 0.25, 0.75, bl, [0.0, 1.0])
        .unwrap();
    grf.text("Label", 0.25, 0.75, bl, [0.0, 1.0]).unwrap();
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    let px = |x: f32| f64::from(x * 720.0f32).round() as i32;
    let py = |y: f32| f64::from(540.0f32 - y * 540.0f32).round() as i32;
    let points: String = (0..4)
        .map(|i| format!("{},{} ", px(tbox.x[i]), py(tbox.y[i])))
        .collect();
    let polygon = format!("<polygon fill=\"black\" points=\"{points}\"/>\n<text");
    assert!(svg.contains(&polygon), "{polygon}\n{svg}");
    // Without the setting there is none.
    let mut grf = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    grf.text("Label", 0.25, 0.75, bl, [0.0, 1.0]).unwrap();
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert!(!svg.contains("<polygon"), "{svg}");
}

/// With equal_aspect, graphics coordinates 0 to 1 span the square PGPLOT's
/// `PGWNAD(0, 1, 0, 1)` makes of its default viewport: inside a margin of
/// four character heights, 60 pixels when the shorter side is 600, with
/// characters 600 / 40 = 15 pixels high at text size 1.
#[test]
fn equal_aspect_draws_on_the_centred_square() {
    let mut options = SvgOptions::default();
    options.width = 800;
    options.height = 600;
    options.equal_aspect = true;
    let mut grf = SvgGrf::new(Vec::new(), options).unwrap();
    grf.line(&[0.0, 1.0], &[0.0, 1.0]).unwrap();
    let cc = Justification::from_code("CC").unwrap();
    grf.text("x", 0.5, 0.5, cc, [0.0, 1.0]).unwrap();
    let svg = String::from_utf8(grf.finish().unwrap()).unwrap();
    assert!(svg.contains("points=\"160,540 640,60 \""), "{svg}");
    assert!(svg.contains("<text x=\"400\" y=\"300\""), "{svg}");
    assert!(svg.contains("font-size=\"15\""), "{svg}");
}

/// With equal_aspect text turns the way its up vector points, at the exact
/// angle, so it sits in the box its extent gives: an up vector pointing left
/// reads upwards, a quarter turn anticlockwise on the screen. Without it the
/// SVG turns text the other way, by C's 5-degree steps, as C's logging
/// backend writes it.
#[test]
fn equal_aspect_turns_text_the_way_its_up_vector_points() {
    let draw = |equal_aspect: bool, up: [f32; 2]| {
        let mut options = SvgOptions::default();
        options.width = 600;
        options.height = 600;
        options.equal_aspect = equal_aspect;
        let mut grf = SvgGrf::new(Vec::new(), options).unwrap();
        let cc = Justification::from_code("CC").unwrap();
        grf.text("x", 0.5, 0.5, cc, up).unwrap();
        String::from_utf8(grf.finish().unwrap()).unwrap()
    };
    let left = [-1.0, 0.0];
    let svg = draw(true, left);
    assert!(svg.contains("transform=\"rotate(-90,300,300)\""), "{svg}");
    let svg = draw(false, left);
    assert!(svg.contains("transform=\"rotate(90,300,300)\""), "{svg}");
    // 32 degrees anticlockwise: C's SVG steps it to 30, the other way.
    let (s, c) = 32f32.to_radians().sin_cos();
    let svg = draw(true, [-s, c]);
    assert!(svg.contains("transform=\"rotate(-32,300,300)\""), "{svg}");
    let svg = draw(false, [-s, c]);
    assert!(svg.contains("transform=\"rotate(30,300,300)\""), "{svg}");
}

/// With equal_aspect text is measured with Helvetica's widths, as wide as the
/// browser draws it in Helvetica, Arial or Liberation Sans, which share them,
/// and the SVG asks for those fonts; without it every character is 0.6 of the
/// height wide, as C's logging backend has it.
#[test]
fn equal_aspect_measures_text_with_helvetica_widths() {
    let width = |equal_aspect: bool, text: &str| {
        let mut options = SvgOptions::default();
        options.width = 600;
        options.height = 600;
        options.equal_aspect = equal_aspect;
        let mut grf = SvgGrf::new(Vec::new(), options).unwrap();
        let bl = Justification::from_code("BL").unwrap();
        let tbox = grf.text_extent(text, 0.0, 0.0, bl, [0.0, 1.0]).unwrap();
        tbox.x[1] - tbox.x[0]
    };
    // Characters 1/32 of the square high; the box is padded by 0.2 of that.
    let h = 1.0 / 32.0;
    let close = |a: f32, b: f32| (a - b).abs() < 1e-6;
    // A hyphen 0.333 of the height, a digit 0.556, a minus sign 0.584.
    assert!(
        close(width(true, "-0"), (0.333 + 0.556 + 0.2) * h),
        "{}",
        width(true, "-0")
    );
    assert!(close(width(true, "\u{2212}0"), (0.584 + 0.556 + 0.2) * h));
    assert!(close(width(true, "Wi"), (0.944 + 0.222 + 0.2) * h));
    assert!(close(width(false, "-0"), (1.2 + 0.2) * 0.02));
    let svg = |equal_aspect: bool| {
        let mut options = SvgOptions::default();
        options.equal_aspect = equal_aspect;
        let mut grf = SvgGrf::new(Vec::new(), options).unwrap();
        let bl = Justification::from_code("BL").unwrap();
        grf.text("x", 0.5, 0.5, bl, [0.0, 1.0]).unwrap();
        String::from_utf8(grf.finish().unwrap()).unwrap()
    };
    assert!(
        svg(true).contains("font-family=\"Helvetica, Arial, 'Liberation Sans', sans-serif\""),
        "{}",
        svg(true)
    );
    assert!(svg(false).contains("font-family=\"sans-serif\""));
}

/// With equal_aspect a Plot lays text out at the height it is drawn: PGPLOT's
/// square is 0.8 of the image's shorter side and a character 1/40 of it, so
/// a character is 1/32 of the square at any image size.
#[test]
fn equal_aspect_reports_the_character_height_it_draws() {
    for (width, height) in [(600, 600), (800, 600), (300, 900)] {
        let mut options = SvgOptions::default();
        options.width = width;
        options.height = height;
        options.equal_aspect = true;
        let mut grf = SvgGrf::new(Vec::new(), options).unwrap();
        assert_eq!(grf.char_height().unwrap(), [0.03125, 0.03125]);
    }
    let mut grf = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    assert_eq!(grf.char_height().unwrap(), [0.02, 0.02]);
}

/// SvgGrf tells a Plot it draws Unicode only when its options say so, so
/// that by default a Plot hands it the ASCII text C's logging backend
/// writes; the PGPLOT layout of equal_aspect does not change that.
#[test]
fn svg_grf_draws_unicode_when_asked() {
    let cap = |equal_aspect: bool, unicode: bool| {
        let mut options = SvgOptions::default();
        options.equal_aspect = equal_aspect;
        options.unicode = unicode;
        SvgGrf::new(Vec::new(), options)
            .unwrap()
            .cap(GrfCap::Unicode, 0)
    };
    assert!(!cap(false, false));
    assert!(!cap(true, false));
    assert!(cap(false, true));
    assert!(cap(true, true));
    let mut log = LogGrf::new(Vec::new());
    assert!(!log.cap(GrfCap::Unicode, 0));
}
